function validate([coins]) {
  if (!Array.isArray(coins) || coins.length < 1 || coins.length > 500) return 'coins needs 1 to 500 rows.';
  const n = coins[0].length;
  if (n < 1 || n > 500) return 'Each row needs 1 to 500 values.';
  for (const row of coins) {
    if (!Array.isArray(row) || row.length !== n) return 'All rows must have the same length.';
    if (row.some(v => !Number.isInteger(v) || v < -1000 || v > 1000)) return 'Each value is an integer from -1000 to 1000.';
  }
  return null;
}

