function maximumAmount(coins) {
  const m = coins.length;
  const n = coins[0].length;
  // dp[i][j][k]: most coins after cell (i, j) with at most k robbers neutralized.
  const dp = Array.from({ length: m }, () => Array.from({ length: n }, () => [0, 0, 0]));
  // Best total just before entering (i, j): from above or from the left; the start is entered with 0.
  const before = (i, j, k) => {
    if (i === 0 && j === 0) return 0;
    const up = i > 0 ? dp[i - 1][j][k] : -Infinity;
    const left = j > 0 ? dp[i][j - 1][k] : -Infinity;
    return Math.max(up, left);
  };
  for (let i = 0; i < m; i++) {
    for (let j = 0; j < n; j++) {
      for (let k = 0; k <= 2; k++) {
        dp[i][j][k] = before(i, j, k) + coins[i][j];
        if (coins[i][j] < 0 && k > 0) {
          dp[i][j][k] = Math.max(dp[i][j][k], before(i, j, k - 1));
        }
      }
    }
  }
  return dp[m - 1][n - 1][2];
}

