function maximumAmount(coins) {
  // Try every right/down route; on a fixed route the two neutralizations go to its two biggest robberies.
  const m = coins.length, n = coins[0].length;
  const route = [];
  let best = -Infinity;
  const walk = (i, j) => {
    route.push(coins[i][j]);
    if (i === m - 1 && j === n - 1) {
      const robbers = route.filter(v => v < 0).sort((a, b) => a - b).slice(0, 2);
      const total = route.reduce((s, v) => s + v, 0) - robbers.reduce((s, v) => s + v, 0);
      best = Math.max(best, total);
    } else {
      if (i + 1 < m) walk(i + 1, j);
      if (j + 1 < n) walk(i, j + 1);
    }
    route.pop();
  };
  walk(0, 0);
  return best;
}

