function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const m = size === 'large' ? 90 + pick(11) : 1 + pick(5);
  const n = size === 'large' ? 90 + pick(11) : 1 + pick(5);
  // The share of robbers and the size of the values vary from grid to grid.
  const robbers = [0.2, 0.5, 0.8, 1][pick(4)];
  const top = size === 'large' ? 1000 : [3, 20, 1000][pick(3)];
  const value = () => (rand() < robbers ? -(1 + pick(top)) : pick(top + 1));
  return [Array.from({ length: m }, () => Array.from({ length: n }, value))];
}
